      --border: rgba(43, 37, 28, 0.16); --text: #24211d; --text-secondary: #6d6257;
      --accent: #1d5f78; --accent-secondary: #b55a30;
      --positive: #1f7a57; --negative: #bd3c2b; --warning: #d99a27;
    }
    html.theme-dark {
      --bg: #11100e; --surface: #1b1916; --surface-hover: #24211d;
      --border: rgba(255, 248, 235, 0.14); --text: #f4efe5; --text-secondary: #b4aa9d;
      --accent: #6fb7cf; --accent-secondary: #e08a5b;
      --positive: #4fb584; --negative: #e1695b; --warning: #e5b85a;
    }
    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
      background: var(--bg); color: var(--text); line-height: 1.45;
      -webkit-font-smoothing: antialiased; letter-spacing: -0.01em;
    }
    .skip-to-content {
      position: absolute; top: -40px; left: 8px; background: var(--accent); color: white;
      padding: 8px 12px; text-decoration: none; border-radius: 4px; z-index: 10000;
    }
    .skip-to-content:focus { top: 8px; }
    .viz-menu { position: fixed; top: 18px; right: 18px; z-index: 1000; }
    .viz-menu-toggle {
      width: 40px; height: 40px; border-radius: 999px; border: 1px solid var(--border);
      background: rgba(255,253,248,.92); color: var(--text); cursor: pointer; display: grid; place-items: center;
      box-shadow: 0 10px 28px rgba(44, 35, 20, .12);
    }
    .viz-menu-dropdown {
      display: none; position: absolute; right: 0; top: 48px; width: 180px; background: var(--surface);
      border: 1px solid var(--border); border-radius: 12px; padding: 8px; box-shadow: 0 18px 50px rgba(44,35,20,.18);
    }
    .viz-menu-dropdown.open { display: block; }
    .viz-menu-dropdown button {
      width: 100%; padding: 10px 12px; border: none; border-radius: 8px; background: transparent;
      color: var(--text); font: inherit; font-size: 13px; cursor: pointer; text-align: left;
    }
    .viz-menu-dropdown button:hover { background: var(--surface-hover); }
    #main-content {
      width: 1600px; height: 1050px; margin: 0 auto; padding: 48px 58px 42px;
      background:
        radial-gradient(circle at 14% 10%, rgba(181, 90, 48, .10), transparent 28%),
        linear-gradient(180deg, #fbf7ed 0%, #f4ede0 100%);
      overflow: hidden;
    }
    .header { display: grid; grid-template-columns: 1fr 390px; gap: 36px; align-items: end; margin-bottom: 16px; }
    .eyebrow { color: var(--accent-secondary); font-size: 14px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; margin-bottom: 10px; }
    h1 { font-size: 48px; line-height: 1.02; letter-spacing: -.045em; color: var(--text); font-weight: 830; max-width: 1000px; }
    .dek { margin-top: 14px; font-size: 18px; color: var(--text-secondary); max-width: 930px; }
    .takeaway {
      background: rgba(255,253,248,.78); border: 1px solid var(--border); border-radius: 18px; padding: 18px 20px;
      box-shadow: 0 18px 50px rgba(80, 62, 32, .08);
    }
    .takeaway strong { display:block; font-size: 15px; text-transform: uppercase; letter-spacing:.08em; color: var(--accent); margin-bottom: 8px; }
    .takeaway p { font-size: 15px; color: var(--text-secondary); }
    .chart-card {
      position: relative; background: rgba(255,253,248,.74); border: 1px solid var(--border); border-radius: 24px;
      box-shadow: 0 24px 70px rgba(80, 62, 32, .10); padding: 18px 20px 12px;
    }
    svg { display:block; width: 100%; height: 790px; overflow: visible; }
    .axis path, .axis line { stroke: rgba(43,37,28,.26); shape-rendering: crispEdges; }
    .axis text { fill: #5e554c; font-size: 13px; }
    .axis-title { fill: #342f2a; font-size: 16px; font-weight: 760; }
    .grid line { stroke: rgba(43,37,28,.10); shape-rendering: crispEdges; }
    .grid path { display:none; }
    .bubble { stroke: rgba(255,253,248,.92); stroke-width: 2.2px; cursor: default; }
    .bubble.dimmed { opacity: .56; }
    .label { font-size: 13px; font-weight: 760; paint-order: stroke; stroke: rgba(255,253,248,.94); stroke-width: 4px; stroke-linejoin: round; fill: #27231e; }
    .label-note { font-size: 12px; font-weight: 650; fill: #6a5f54; paint-order: stroke; stroke: rgba(255,253,248,.95); stroke-width: 3px; }
    .callout-line { stroke: rgba(38,34,30,.42); stroke-width: 1.2; stroke-dasharray: 3 4; }
    .trend { fill: none; stroke: #263640; stroke-width: 3.2; stroke-linecap: round; opacity: .8; }
    .trend-band { fill: rgba(29,95,120,.08); }
    .median-line { stroke: rgba(36,33,29,.28); stroke-width: 1.1; stroke-dasharray: 6 6; }
    .quadrant-label { fill: #7a6f64; font-size: 12px; font-weight: 720; letter-spacing: .02em; text-transform: uppercase; }
    .legend-title { fill: #2f2a25; font-weight: 800; font-size: 13px; letter-spacing: .02em; }
    .legend-text { fill: #62584e; font-size: 12px; }
    .footer { display:flex; justify-content: space-between; gap: 24px; margin-top: 14px; color: var(--text-secondary); font-size: 12px; }
    .footer b { color: var(--text); }
    .hidden-canvas { position:absolute; width:1px; height:1px; opacity:0; pointer-events:none; }
    @media print { .viz-menu { display:none; } #main-content { box-shadow:none; } }
  </style>
</head>
<body>
  <a href="#main-content" class="skip-to-content">Skip to content</a>
  <div class="viz-menu">
    <button class="viz-menu-toggle" onclick="toggleMenu()" aria-label="Menu">
      <svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <line x1="3" y1="5" x2="17" y2="5"/><line x1="3" y1="10" x2="17" y2="10"/><line x1="3" y1="15" x2="17" y2="15"/>
      </svg>
    </button>
    <div class="viz-menu-dropdown" id="vizMenuDropdown">
      <button onclick="cycleTheme()"><span id="themeIcon">☀️</span> <span id="themeLabel">Light</span></button>
      <button onclick="downloadImage()">📥 Download PNG</button>
      <button onclick="window.print()">🖨️ Print / PDF</button>
    </div>
  </div>
  <main id="main-content" role="main">
    <section class="header" aria-labelledby="chart-title">
      <div>
        <div class="eyebrow">30-country education outcomes benchmark · circa 2022–2023</div>
        <h1 id="chart-title">More education spending does not map neatly to better outcomes</h1>
        <p class="dek">PISA performance, university enrollment and youth labor-market outcomes scatter widely at similar spending levels. Bubble size shows tertiary enrollment; color shows youth unemployment.</p>
      </div>
      <aside class="takeaway" aria-label="Key takeaway">
        <strong>Analytical read</strong>
        <p>Singapore, Japan and South Korea sit in the “efficient” corner: high PISA and low youth unemployment at below-median spending. High-spending Sweden and Costa Rica show how labor-market and learning outcomes can diverge.</p>
      </aside>
    </section>
    <section class="chart-card" aria-label="Bubble scatter chart of education spending and outcomes">
      <svg id="chart" role="img" aria-label="Bubble chart. X axis education spending as percent of GDP, Y axis average PISA score, bubble area is tertiary enrollment rate, color is youth unemployment rate."></svg>
      <canvas id="accessibilityChart" class="hidden-canvas" role="img" aria-label="Invisible Chart.js accessibility validation chart"></canvas>
    </section>
    <section class="footer" aria-label="Source and encoding notes">
      <div><b>Source:</b> source_data.json datasets: education spending (% GDP), 2022 PISA average, tertiary enrollment (% cohort), youth unemployment (% labor force age 15–24).</div>
      <div><b>Encoding:</b> x = spending, y = PISA, area = enrollment, color = youth unemployment. Dashed lines mark sample medians.</div>
    </section>
  </main>
  <script>
    function toggleMenu() {
      var dropdown = document.getElementById('vizMenuDropdown');
      if (dropdown) dropdown.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      if (!e.target.closest('.viz-menu')) document.getElementById('vizMenuDropdown').classList.remove('open');
    });
    function cycleTheme() {
      var html = document.documentElement;
      var next = html.classList.contains('theme-light') ? 'dark' : 'light';
      html.className = 'theme-' + next;
      document.getElementById('themeIcon').textContent = next === 'light' ? '☀️' : '🌙';
      document.getElementById('themeLabel').textContent = next.charAt(0).toUpperCase() + next.slice(1);
    }
    function downloadImage() {
      htmlToImage.toPng(document.getElementById('main-content'), { pixelRatio: 2, backgroundColor: '#f7f3ea' })
        .then(function(dataUrl) { var a = document.createElement('a'); a.download = 'education-investment-outcomes.png'; a.href = dataUrl; a.click(); });
    }

    var data = [
      {country:'Finland',region:'Europe',spending:5.9,pisa:507,enrollment:90,unemp:17.2},
      {country:'South Korea',region:'Asia',spending:4.5,pisa:527,enrollment:98,unemp:6.4},
      {country:'Japan',region:'Asia',spending:3.2,pisa:536,enrollment:65,unemp:4.1},
      {country:'Singapore',region:'Asia',spending:2.9,pisa:561,enrollment:82,unemp:6.7},
      {country:'Estonia',region:'Europe',spending:5.2,pisa:526,enrollment:72,unemp:11.8},
      {country:'Canada',region:'Americas',spending:5.3,pisa:504,enrollment:75,unemp:10.8},
      {country:'Germany',region:'Europe',spending:4.6,pisa:480,enrollment:70,unemp:5.8},
      {country:'United States',region:'Americas',spending:5.0,pisa:489,enrollment:88,unemp:8.0},
      {country:'United Kingdom',region:'Europe',spending:5.2,pisa:494,enrollment:62,unemp:11.3},
      {country:'France',region:'Europe',spending:5.4,pisa:478,enrollment:68,unemp:17.3},
      {country:'Sweden',region:'Europe',spending:7.2,pisa:487,enrollment:74,unemp:20.1},
      {country:'Norway',region:'Europe',spending:6.6,pisa:477,enrollment:82,unemp:10.3},
      {country:'Denmark',region:'Europe',spending:6.4,pisa:489,enrollment:80,unemp:10.0},
      {country:'Netherlands',region:'Europe',spending:5.1,pisa:493,enrollment:85,unemp:8.4},
      {country:'Switzerland',region:'Europe',spending:5.0,pisa:503,enrollment:60,unemp:7.9},
      {country:'Australia',region:'Oceania',spending:5.1,pisa:494,enrollment:110,unemp:8.5},
      {country:'New Zealand',region:'Oceania',spending:5.5,pisa:493,enrollment:80,unemp:9.2},
      {country:'Ireland',region:'Europe',spending:3.5,pisa:504,enrollment:78,unemp:10.5},
      {country:'Poland',region:'Europe',spending:4.6,pisa:496,enrollment:67,unemp:11.5},
      {country:'Czech Republic',region:'Europe',spending:4.4,pisa:487,enrollment:63,unemp:7.6},
      {country:'Italy',region:'Europe',spending:4.0,pisa:471,enrollment:64,unemp:23.7},
      {country:'Spain',region:'Europe',spending:4.3,pisa:473,enrollment:91,unemp:28.4},
      {country:'Greece',region:'Europe',spending:3.7,pisa:445,enrollment:110,unemp:27.2},
      {country:'Portugal',region:'Europe',spending:4.9,pisa:477,enrollment:66,unemp:18.8},
      {country:'Brazil',region:'Americas',spending:6.1,pisa:379,enrollment:55,unemp:21.3},
      {country:'Mexico',region:'Americas',spending:4.3,pisa:395,enrollment:43,unemp:6.8},
      {country:'Chile',region:'Americas',spending:5.4,pisa:412,enrollment:90,unemp:18.5},
      {country:'Turkey',region:'Asia',spending:4.3,pisa:453,enrollment:105,unemp:17.6},
      {country:'Israel',region:'Asia',spending:6.2,pisa:458,enrollment:68,unemp:7.1},
      {country:'Costa Rica',region:'Americas',spending:7.0,pisa:402,enrollment:57,unemp:30.2}
    ];

    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') { console.error('Chart.js library not loaded - check CDN inclusion'); return null; }
        try {
          if (this.charts.has(canvasId)) { this.charts.get(canvasId).destroy(); this.charts.delete(canvasId); }
          var ctx = document.getElementById(canvasId);
          if (!ctx) { console.error('Canvas element not found: ' + canvasId); return null; }
          ctx.setAttribute('role', 'img');
          if (!ctx.getAttribute('aria-label')) ctx.setAttribute('aria-label', 'Chart visualization');
          var chart = new Chart(ctx, config);
          ctx.chart = chart; this.charts.set(canvasId, chart); return chart;
        } catch (error) { console.error('Chart initialization failed:', error); return null; }
      }
    };
    function initAccessibilityChart() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
      ChartManager.safeInit('accessibilityChart', {
        type: 'scatter',
        data: { datasets: [{ label: 'Countries', data: data.map(function(d){ return {x:d.spending, y:d.pisa}; }) }] },
        options: { responsive: true, maintainAspectRatio: false, plugins: { tooltip: { enabled: true }, legend: { display: false } }, scales: { x: { display: false }, y: { display: false } } }
      });
    }

    function median(values) {
      var sorted = values.slice().sort(function(a,b){ return a-b; });
      var mid = Math.floor(sorted.length / 2);
      return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
    }
    function quadraticFit(points) {
      var n = points.length, sx=0, sx2=0, sx3=0, sx4=0, sy=0, sxy=0, sx2y=0;
      points.forEach(function(p){ var x=p.spending, y=p.pisa, x2=x*x; sx+=x; sx2+=x2; sx3+=x2*x; sx4+=x2*x2; sy+=y; sxy+=x*y; sx2y+=x2*y; });
      var A = [[n,sx,sx2],[sx,sx2,sx3],[sx2,sx3,sx4]], B = [sy,sxy,sx2y];
      for (var i=0;i<3;i++) {
        var max=i; for (var j=i+1;j<3;j++) if (Math.abs(A[j][i]) > Math.abs(A[max][i])) max=j;
        var ta=A[i]; A[i]=A[max]; A[max]=ta; var tb=B[i]; B[i]=B[max]; B[max]=tb;
        var pivot=A[i][i]; for (var k=i;k<3;k++) A[i][k]/=pivot; B[i]/=pivot;
        for (var r=0;r<3;r++) if (r!==i) { var f=A[r][i]; for (var c=i;c<3;c++) A[r][c]-=f*A[i][c]; B[r]-=f*B[i]; }
      }
      return function(x) { return B[0] + B[1]*x + B[2]*x*x; };
    }

    function renderChart() {
      var svg = d3.select('#chart');
      var width = 1460, height = 790;
      var margin = {top: 34, right: 285, bottom: 94, left: 88};
      var innerW = width - margin.left - margin.right;
      var innerH = height - margin.top - margin.bottom;
      svg.attr('viewBox', '0 0 ' + width + ' ' + height);

      var x = d3.scaleLinear().domain([2.6, 7.45]).range([margin.left, margin.left + innerW]);
      var y = d3.scaleLinear().domain([360, 575]).range([margin.top + innerH, margin.top]);
      var r = d3.scaleSqrt().domain([40, 112]).range([7, 31]);
      var color = d3.scaleLinear().domain([4, 11, 20, 31]).range(['#236c8e', '#6fa87e', '#e0a33a', '#bd3c2b']).clamp(true);
      var medSpend = median(data.map(function(d){return d.spending;}));
      var medPisa = median(data.map(function(d){return d.pisa;}));

      svg.append('defs').append('filter').attr('id','softShadow').attr('x','-30%').attr('y','-30%').attr('width','160%').attr('height','160%')
        .html('<feDropShadow dx="0" dy="7" stdDeviation="5" flood-color="#5b4a35" flood-opacity="0.16"/>');
      var g = svg.append('g');
      g.append('g').attr('class','grid').attr('transform','translate(0,' + (margin.top + innerH) + ')')
        .call(d3.axisBottom(x).tickValues([3,4,5,6,7]).tickSize(-innerH).tickFormat(''));
      g.append('g').attr('class','grid').attr('transform','translate(' + margin.left + ',0)')
        .call(d3.axisLeft(y).tickValues([400,450,500,550]).tickSize(-innerW).tickFormat(''));
      g.append('line').attr('class','median-line').attr('x1',x(medSpend)).attr('x2',x(medSpend)).attr('y1',margin.top).attr('y2',margin.top+innerH);
      g.append('line').attr('class','median-line').attr('x1',margin.left).attr('x2',margin.left+innerW).attr('y1',y(medPisa)).attr('y2',y(medPisa));
      g.append('text').attr('class','quadrant-label').attr('x',x(2.72)).attr('y',y(558)).text('Efficient outcomes');
      g.append('text').attr('class','quadrant-label').attr('x',x(6.1)).attr('y',y(558)).text('High-spend, high-PISA');
      g.append('text').attr('class','quadrant-label').attr('x',x(6.05)).attr('y',y(381)).text('High-spend disconnects');

      var fit = quadraticFit(data);
      var trendData = d3.range(2.75, 7.31, 0.05).map(function(v){ return {x:v, y:fit(v)}; });
      var line = d3.line().x(function(d){return x(d.x);}).y(function(d){return y(d.y);}).curve(d3.curveCatmullRom.alpha(.5));
      var area = d3.area().x(function(d){return x(d.x);}).y0(function(d){return y(d.y-12);}).y1(function(d){return y(d.y+12);}).curve(d3.curveCatmullRom.alpha(.5));
      g.append('path').datum(trendData).attr('class','trend-band').attr('d', area);
      g.append('path').datum(trendData).attr('class','trend').attr('d', line);
      g.append('text').attr('x', x(3.05)).attr('y', y(fit(3.05)-23)).attr('class','legend-text').style('font-weight',700).text('Quadratic trend: weak, non-linear association');

      g.append('g').attr('class','axis').attr('transform','translate(0,' + (margin.top + innerH) + ')')
        .call(d3.axisBottom(x).tickValues([3,4,5,6,7]).tickFormat(function(d){ return d + '%'; }));
      g.append('g').attr('class','axis').attr('transform','translate(' + margin.left + ',0)')
        .call(d3.axisLeft(y).tickValues([400,450,500,550]));
      g.append('text').attr('class','axis-title').attr('x', margin.left + innerW / 2).attr('y', height - 28).attr('text-anchor','middle').text('Education expenditure (% of GDP)');
      g.append('text').attr('class','axis-title').attr('transform','rotate(-90)').attr('x', -(margin.top + innerH / 2)).attr('y', 24).attr('text-anchor','middle').text('Average PISA score (reading, math, science)');

      var labelSet = new Set(['Singapore','Japan','South Korea','Estonia','Finland','Sweden','Costa Rica','Brazil','Greece','Spain','Australia','Israel']);
      g.selectAll('.bubble').data(data).enter().append('circle')
        .attr('class', function(d){ return 'bubble' + (labelSet.has(d.country) ? '' : ' dimmed'); })
        .attr('cx', function(d){ return x(d.spending); })
        .attr('cy', function(d){ return y(d.pisa); })
        .attr('r', function(d){ return r(d.enrollment); })
        .attr('fill', function(d){ return color(d.unemp); })
        .attr('fill-opacity', .86)
        .attr('filter','url(#softShadow)')
        .append('title').text(function(d){ return d.country + ': spending ' + d.spending + '% GDP, PISA ' + d.pisa + ', enrollment ' + d.enrollment + '%, youth unemployment ' + d.unemp + '%'; });

      var labelOffsets = {
        Singapore:[20,-18,'start'], Japan:[18,-3,'start'], 'South Korea':[18,18,'start'], Estonia:[15,-15,'start'], Finland:[18,-22,'start'],
        Sweden:[-20,-20,'end'], 'Costa Rica':[-18,18,'end'], Brazil:[18,14,'start'], Greece:[-18,20,'end'], Spain:[-16,-20,'end'], Australia:[18,24,'start'], Israel:[16,18,'start']
      };
      var notes = {
        Singapore:'low spend · top PISA', Japan:'lowest unemployment', 'South Korea':'high PISA · high enrollment', Estonia:'moderate spend · high PISA',
        Finland:'high PISA, higher youth joblessness', Sweden:'highest spend, mixed outcomes', 'Costa Rica':'high spend · highest youth unemployment',
        Brazil:'high spend · low PISA', Greece:'very high enrollment, weak labor market', Spain:'high enrollment, high youth unemployment',
        Australia:'largest enrollment bubble', Israel:'high spend, low unemployment'
      };
      var labels = data.filter(function(d){ return labelSet.has(d.country); });
      labels.forEach(function(d){
        var off = labelOffsets[d.country], lx = x(d.spending) + off[0], ly = y(d.pisa) + off[1];
        g.append('line').attr('class','callout-line').attr('x1',x(d.spending)).attr('y1',y(d.pisa)).attr('x2',lx - (off[2] === 'end' ? -4 : 4)).attr('y2',ly - 5);
        g.append('text').attr('class','label').attr('x',lx).attr('y',ly).attr('text-anchor',off[2]).text(d.country);
        g.append('text').attr('class','label-note').attr('x',lx).attr('y',ly+16).attr('text-anchor',off[2]).text(notes[d.country]);
      });

      var legendX = margin.left + innerW + 58, legendY = margin.top + 8;
      g.append('text').attr('class','legend-title').attr('x',legendX).attr('y',legendY).text('Youth unemployment');
      g.append('text').attr('class','legend-text').attr('x',legendX).attr('y',legendY+18).text('% of labor force age 15–24');
      var grad = svg.select('defs').append('linearGradient').attr('id','unempGrad').attr('x1','0%').attr('x2','100%').attr('y1','0%').attr('y2','0%');
      [[0,'#236c8e'],[.33,'#6fa87e'],[.68,'#e0a33a'],[1,'#bd3c2b']].forEach(function(s){ grad.append('stop').attr('offset',(s[0]*100)+'%').attr('stop-color',s[1]); });
      g.append('rect').attr('x',legendX).attr('y',legendY+32).attr('width',185).attr('height',14).attr('rx',7).attr('fill','url(#unempGrad)');
      var lgScale = d3.scaleLinear().domain([4,31]).range([legendX, legendX+185]);
      [5,15,25,30].forEach(function(v){
        g.append('line').attr('x1',lgScale(v)).attr('x2',lgScale(v)).attr('y1',legendY+50).attr('y2',legendY+55).attr('stroke','#82776b');
        g.append('text').attr('class','legend-text').attr('x',lgScale(v)).attr('y',legendY+70).attr('text-anchor','middle').text(v+'%');
      });
      g.append('text').attr('class','legend-title').attr('x',legendX).attr('y',legendY+112).text('Tertiary enrollment');
      g.append('text').attr('class','legend-text').attr('x',legendX).attr('y',legendY+130).text('% of relevant age cohort');
      [55,80,110].forEach(function(v,i){
        var cx = legendX + 27 + i*66, cy = legendY + 176;
        g.append('circle').attr('cx',cx).attr('cy',cy).attr('r',r(v)).attr('fill','none').attr('stroke','#62584e').attr('stroke-width',1.4);
        g.append('text').attr('class','legend-text').attr('x',cx).attr('y',legendY+225).attr('text-anchor','middle').text(v+'%');
      });
      g.append('text').attr('class','legend-title').attr('x',legendX).attr('y',legendY+270).text('Reading the chart');
      var bullets = [
        'Higher bubbles perform better on PISA.',
        'Larger bubbles enroll more students in tertiary education.',
        'Redder bubbles have tougher youth labor markets.',
